def test_the_bucket_empties_refuses_and_refills() -> None:
    """A bucket holds `requests` tokens and refills one every `window_seconds / requests`
    seconds.
    """
    state, decision = take_token(None, POLICY, 0)
    assert (decision.allowed, decision.remaining, decision.reset) == (True, 1, 5)
    state, decision = take_token(state, POLICY, 0)
    assert (decision.allowed, decision.remaining, decision.reset) == (True, 0, 10)
    state, decision = take_token(state, POLICY, 1)
    assert (decision.allowed, decision.retry_after) == (False, 4)
    state, decision = take_token(state, POLICY, 5)
    assert decision.allowed
    # A long pause refills the bucket up to its size, not beyond.
    _, decision = take_token(state, POLICY, 3600)
    assert (decision.allowed, decision.remaining) == (True, 1)


def test_buckets_are_per_subject_and_follow_a_fake_clock() -> None:
    now = [0.0]
    limiter = RateLimiter(InMemoryRateLimitStore(), clock=lambda: now[0])
    assert [limiter.consume(POLICY, "alice").allowed for _ in range(3)] == [True, True, False]
    assert limiter.consume(POLICY, "bob").allowed
    now[0] += 5
    assert limiter.consume(POLICY, "alice").allowed


def test_rate_limit_header_fields() -> None:
    """draft-ietf-httpapi-ratelimit-headers: RateLimit-Policy (q, w) and RateLimit (r, t);
    Retry-After on refusal.
    """
    _, refused = take_token(BucketState(tokens=0, updated_at=0), POLICY, 0)
    assert rate_limit_headers(POLICY, refused) == {
        "RateLimit-Policy": '"example";q=2;w=10',
        "RateLimit": '"example";r=0;t=5',
        "Retry-After": "5",
    }
    _, allowed = take_token(None, POLICY, 0)
    assert "Retry-After" not in rate_limit_headers(POLICY, allowed)


def test_a_limit_by_tenant_keeps_one_bucket_per_tenant() -> None:
    """`by: tenant`: one tenant using up its bucket does not starve another (noisy-neighbour
    isolation).
    """
    per_tenant = RateLimit(name="example", requests=1, window_seconds=60, by="tenant")
    limiter = RateLimiter(InMemoryRateLimitStore(), clock=lambda: 0.0)
    assert limiter.consume(per_tenant, "tenant-a").allowed
    assert not limiter.consume(per_tenant, "tenant-a").allowed
    assert limiter.consume(per_tenant, "tenant-b").allowed
